SELECT CASE WHEN s.city IN ('Singapore', 'Berlin') THEN 'core' ELSE 'other' END city_group, QUARTER(s.opened_date) opened_quarter, COUNT(CASE WHEN o.status = 'CANCELLED' THEN 1 END) cancelled_count, SUM(CASE WHEN o.status = 'SHIPPED' THEN 1 ELSE 0 END) shipped_count FROM orders o JOIN stores s ON o.store_id = s.id JOIN customers c ON o.customer_id = c.id GROUP BY CASE WHEN s.city IN ('Singapore', 'Berlin') THEN 'core' ELSE 'other' END, QUARTER(s.opened_date) ORDER BY city_group, opened_quarter;
